CREATE OR REPLACE FUNCTION public.is_active_member() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role IN ('owner','member')) $$;
REVOKE ALL ON FUNCTION public.is_active_member() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.is_active_member() TO authenticated,service_role;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated,service_role;
REVOKE ALL ON FUNCTION public.get_insights(text) FROM PUBLIC,anon;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['user_settings','focus_sessions','interruptions','energy_ratings','prime_sessions','event_flags','manual_blocks','recurring_blocks','recurring_skips','checkin_dismissals','push_subscriptions','push_focus_deadlines','push_presence','reminder_claims','allowed_emails'] LOOP EXECUTE format('CREATE POLICY "active membership required" ON public.%I AS RESTRICTIVE FOR ALL TO authenticated USING (public.is_active_member()) WITH CHECK (public.is_active_member())',t); END LOOP; END $$;
CREATE OR REPLACE FUNCTION public.claim_reminder(_key text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_active_member() OR length(_key)>500 THEN RETURN false; END IF; INSERT INTO public.reminder_claims(user_id,reminder_key) VALUES(auth.uid(),_key) ON CONFLICT DO NOTHING; RETURN FOUND; END $$;
CREATE OR REPLACE FUNCTION public.replace_block_occurrence(_block uuid,_date date,_replacement jsonb) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.recurring_blocks WHERE id=_block AND user_id=auth.uid()) THEN RAISE EXCEPTION 'Block unavailable'; END IF; INSERT INTO public.recurring_skips(user_id,block_id,local_date) VALUES(auth.uid(),_block,_date) ON CONFLICT DO NOTHING; INSERT INTO public.manual_blocks(id,user_id,kind,label,start_at,end_at) VALUES((_replacement->>'id')::uuid,auth.uid(),_replacement->>'kind',_replacement->>'label',(_replacement->>'start_at')::timestamptz,(_replacement->>'end_at')::timestamptz); END $$;
REVOKE ALL ON FUNCTION public.replace_block_occurrence(uuid,date,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.replace_block_occurrence(uuid,date,jsonb) TO authenticated;
CREATE OR REPLACE FUNCTION public.convert_manual_block(_manual uuid,_series jsonb) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ BEGIN IF _manual IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.manual_blocks WHERE id=_manual AND user_id=auth.uid()) THEN RAISE EXCEPTION 'Block unavailable'; END IF; INSERT INTO public.recurring_blocks(id,user_id,kind,label,start_time,end_time,days) VALUES((_series->>'id')::uuid,auth.uid(),_series->>'kind',_series->>'label',(_series->>'start_time')::time,(_series->>'end_time')::time,ARRAY(SELECT jsonb_array_elements_text(_series->'days')::int)); IF _manual IS NOT NULL THEN DELETE FROM public.manual_blocks WHERE id=_manual AND user_id=auth.uid(); END IF; END $$;
REVOKE ALL ON FUNCTION public.convert_manual_block(uuid,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.convert_manual_block(uuid,jsonb) TO authenticated;
CREATE OR REPLACE FUNCTION public.restore_history_session(_row jsonb,_interruptions jsonb) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE r public.focus_sessions; i public.interruptions; BEGIN r:=jsonb_populate_record(NULL::public.focus_sessions,_row); IF r.user_id IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Not your session'; END IF; INSERT INTO public.focus_sessions SELECT r.* ON CONFLICT(id) DO NOTHING; FOR i IN SELECT * FROM jsonb_populate_recordset(NULL::public.interruptions,_interruptions) LOOP IF i.user_id IS DISTINCT FROM auth.uid() OR i.session_id IS DISTINCT FROM r.id THEN RAISE EXCEPTION 'Not your interruption'; END IF; INSERT INTO public.interruptions SELECT i.* ON CONFLICT(id) DO NOTHING; END LOOP; END $$;
REVOKE ALL ON FUNCTION public.restore_history_session(jsonb,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.restore_history_session(jsonb,jsonb) TO authenticated;